package in.kabadiwala.connect.integration; import org.springframework.beans.factory.annotation.Value; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.stereotype.Service; import org.springframework.web.multipart.MultipartFile; import java.nio.file.*; import java.util.*; @Service @ConditionalOnProperty(name="app.storage.provider",havingValue="local",matchIfMissing=true) public class LocalStorageService implements StorageService {private final Path root;public LocalStorageService(@Value("${app.storage.local-dir:./uploads}")String dir){root=Paths.get(dir).toAbsolutePath().normalize();try{Files.createDirectories(root);}catch(Exception e){throw new IllegalStateException(e);}} public Stored store(MultipartFile f,String folder){try{String ext=Optional.ofNullable(f.getOriginalFilename()).filter(x->x.contains(".")).map(x->x.substring(x.lastIndexOf('.'))).orElse("");String key=folder+"/"+UUID.randomUUID()+ext;Path p=root.resolve(key).normalize();if(!p.startsWith(root))throw new IllegalArgumentException("Invalid path");Files.createDirectories(p.getParent());f.transferTo(p);return new Stored(key,"/api/v1/files/"+key);}catch(Exception e){throw new IllegalArgumentException("Upload failed");}} public byte[] read(String key){try{return Files.readAllBytes(root.resolve(key).normalize());}catch(Exception e){throw new IllegalArgumentException("File not found");}}}
